CREATE   VIEW bi.OptimizationSolve AS
SELECT f.* FROM dss.Fact_OptimizationSolve f
JOIN bi.CompletedRuns r ON r.PlanningRunKey=f.PlanningRunKey;

CREATE   VIEW bi.RunSummary AS
SELECT f.* FROM dss.Fact_RunSummary f
JOIN bi.CompletedRuns r ON r.PlanningRunKey=f.PlanningRunKey;

CREATE   VIEW bi.SimulationDaily AS
SELECT f.* FROM dss.Fact_SimulationDaily f
JOIN bi.CompletedRuns r ON r.PlanningRunKey=f.PlanningRunKey;

CREATE   VIEW bi.SimulationOrder AS
SELECT f.* FROM dss.Fact_SimulationOrder f
JOIN bi.CompletedRuns r ON r.PlanningRunKey=f.PlanningRunKey;

CREATE   VIEW cxcontrol.DimActivity AS
SELECT EventCode,EventName,QuantityMeaning FROM dss.Dim_EventType
WHERE EventCode IN('PRODUCTION_REQUEST','PRODUCTION_START','PRODUCTION_GOOD','BOM_ISSUE','BUY_ORDER');

CREATE   VIEW cxolap.DimEvaluationCohort AS
SELECT CONVERT(nvarchar(30),v.Cohort) EvaluationCohort
FROM (VALUES(N'OPENING_OVERDUE'),(N'DUE_IN_RUN'),(N'FUTURE_DUE')) v(Cohort);

CREATE   VIEW cxolap.DimLocation AS
SELECT LocationKey,COALESCE(LocationName,N'Unknown') LocationName,
 COALESCE(LocationType,N'UNKNOWN') LocationType FROM dw.Dim_Location;

CREATE   VIEW cxolap.DimOrderStatus AS
SELECT DISTINCT OrderStatus FROM dss.Fact_SimulationOrder
UNION SELECT CONVERT(nvarchar(30),N'NOT_APPLICABLE');

CREATE   VIEW cxolap.DimSolveStatus AS
SELECT DISTINCT SolverStatus FROM dss.Fact_OptimizationSolve
UNION SELECT CONVERT(nvarchar(50),N'NOT_APPLICABLE');

CREATE   VIEW cxolap.FactRunDay AS
SELECT f.PlanningRunKey,f.DateKey,CONVERT(bigint,1) CalendarDayCount
FROM cxolap.FactSimulationDaily f GROUP BY f.PlanningRunKey,f.DateKey;

CREATE   VIEW cxolap.FactRunSummary AS
SELECT f.*,CONVERT(bigint,1) RunCount
FROM dss.Fact_RunSummary f JOIN cxolap.DimRun r ON r.PlanningRunKey=f.PlanningRunKey;
